package io.undertow.client.http;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
public class Probe2 {
  static void incremental(String s, int chunk) {
    HttpResponseBuilder b = new HttpResponseBuilder();
    byte[] all = s.getBytes(StandardCharsets.US_ASCII);
    int off=0;
    try {
      while(off<all.length && !b.getParseState().isComplete()) {
        int len=Math.min(chunk, all.length-off);
        ByteBuffer buf=ByteBuffer.wrap(all, off, len).slice();
        ResponseParser.INSTANCE.handle(buf, b.getParseState(), b);
        off += (len - buf.remaining());
        if (buf.remaining()==len) { // no progress
          System.out.println("STUCK at off="+off+" chunk="+chunk); return;
        }
      }
      System.out.println("chunk="+chunk+" complete="+b.getParseState().isComplete()+" code="+b.getStatusCode()+" reason="+b.getReasonPhrase()+" headers="+b.getResponseHeaders()+" consumed="+off+" total="+all.length);
    } catch(Throwable t) { System.out.println("chunk="+chunk+" ERR "+t); }
  }
  public static void main(String[] a) {
    String s="HTTP/1.1 200 OK\r\nHeader: value\r\nX-Fold: one\r\n two\r\n\r\nBODY";
    for(int c: new int[]{1,2,3,5,7,10,20,1000}) incremental(s,c);
    // no headers
    for(int c: new int[]{1,2,3}) incremental("HTTP/1.1 204 No Content\r\n\r\n",c);
  }
}
