        assertEquals(0x05, AjpConstants.ATTR_QUERY_STRING);
        assertEquals(0x0A, AjpConstants.ATTR_REQ_ATTRIBUTE);
        assertEquals(0x0D, AjpConstants.ATTR_STORED_METHOD);
        assertEquals(0xFF, AjpConstants.ATTR_ARE_DONE);
    }

