        assertEquals(0xA003, AjpConstants.HEADER_MAP.get(Headers.ACCEPT_ENCODING).intValue());
        assertEquals(0xA007, AjpConstants.HEADER_MAP.get(Headers.CONTENT_TYPE).intValue());
        assertEquals(0xA008, AjpConstants.HEADER_MAP.get(Headers.CONTENT_LENGTH).intValue());
        assertEquals(0xA00A, AjpConstants.HEADER_MAP.get(Headers.COOKIE2).intValue());
        assertEquals(0xA00E, AjpConstants.HEADER_MAP.get(Headers.USER_AGENT).intValue());
        assertNull(AjpConstants.HEADER_MAP.get(Headers.HOST + "-missing"));
    }

