package io.undertow.protocols.ajp;

import static io.undertow.protocols.ajp.AjpTestSupport.newClientChannel;
import static io.undertow.protocols.ajp.AjpTestSupport.putInt;
import static io.undertow.protocols.ajp.AjpTestSupport.putString;
import static io.undertow.protocols.ajp.AjpTestSupport.responseFrame;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.ByteBuffer;
import java.util.Collection;

import io.undertow.connector.PooledByteBuffer;
import io.undertow.server.protocol.framed.AbstractFramedStreamSourceChannel;
import io.undertow.server.protocol.framed.FrameHeaderData;
import io.undertow.server.protocol.framed.SendFrameHeader;
import io.undertow.util.HeaderMap;
import io.undertow.util.Headers;
import io.undertow.util.HttpString;
import io.undertow.util.ImmediatePooledByteBuffer;
import io.undertow.util.Methods;
import org.junit.jupiter.api.Test;
import org.xnio.Option;
import org.xnio.OptionMap;

class AjpClientChannelTest {

    @Test
    void sendRequestRejectsASecondConcurrentRequestUntilBothSidesComplete() {
        AjpClientChannel channel = newClientChannel();
        HeaderMap headers = new HeaderMap();
        headers.put(Headers.CONTENT_LENGTH, "0");

        AjpClientRequestClientStreamSinkChannel request = AjpTestSupport.request(channel, Methods.GET, "/",
                headers, AjpTestSupport.attachable());
        assertNotNull(request);
        assertSame(request, channel.sink);

        IllegalStateException exception = assertThrows(IllegalStateException.class,
                () -> AjpTestSupport.request(channel, Methods.GET, "/", new HeaderMap(), AjpTestSupport.attachable()));
        assertEquals("AJP request already in progress", exception.getMessage());

        channel.sinkDone();
        // still waiting for a response
        assertThrows(IllegalStateException.class,
                () -> AjpTestSupport.request(channel, Methods.GET, "/", new HeaderMap(), AjpTestSupport.attachable()));

        channel.sourceDone();
        AjpClientRequestClientStreamSinkChannel next = AjpTestSupport.request(channel, Methods.GET, "/",
                new HeaderMap(), AjpTestSupport.attachable());
        assertNotNull(next);
        assertNull(channel.source);
    }

    @Test
    void parseFrameBuildsSendHeadersResponse() throws Exception {
        AjpClientChannel channel = newClientChannel();
        FrameHeaderData data = channel.parseFrame(responseFrame(AjpConstants.FRAME_TYPE_SEND_HEADERS, 1, buffer -> {
            putInt(buffer, 200);
            putString(buffer, "OK");
            putInt(buffer, 1);
            putInt(buffer, 0xA001);
            putString(buffer, "text/plain");
        }));

        AjpClientChannel.SendHeadersResponse response = assertInstanceOf(AjpClientChannel.SendHeadersResponse.class, data);
        assertEquals(0, response.getFrameLength());
        assertNull(response.getExistingChannel());

        AjpClientResponseStreamSourceChannel source = assertInstanceOf(AjpClientResponseStreamSourceChannel.class,
                channel.createChannel(response, null));
        assertEquals(200, source.getStatusCode());
        assertEquals("OK", source.getReasonPhrase());
        assertEquals("text/plain", source.getHeaders().getFirst(Headers.CONTENT_TYPE));
        assertSame(source, channel.source);
        assertEquals(1, channel.getReceivers().size());
    }

    @Test
    void parseFrameRecognisesRequestBodyChunkAndSendBodyChunk() throws Exception {
        AjpClientChannel channel = newClientChannel();

        FrameHeaderData requested = channel.parseFrame(responseFrame(AjpConstants.FRAME_TYPE_REQUEST_BODY_CHUNK, 2,
                buffer -> putInt(buffer, 321)));
        AjpClientChannel.RequestBodyChunk bodyChunk = assertInstanceOf(AjpClientChannel.RequestBodyChunk.class, requested);
        assertEquals(321, bodyChunk.getLength());
        assertEquals(0, bodyChunk.getFrameLength());

        FrameHeaderData body = channel.parseFrame(responseFrame(AjpConstants.FRAME_TYPE_SEND_BODY_CHUNK, 2,
                buffer -> putInt(buffer, 10)));
        AjpClientChannel.SendBodyChunk sendBodyChunk = assertInstanceOf(AjpClientChannel.SendBodyChunk.class, body);
        // AJP body chunks have a trailing null byte that is part of the frame
        assertEquals(11, sendBodyChunk.getFrameLength());
    }

    @Test
    void parseFrameRecognisesEndResponseAndPersistentFlag() throws Exception {
        AjpClientChannel channel = newClientChannel();
        assertTrue(channel.isOpen());

        FrameHeaderData data = channel.parseFrame(responseFrame(AjpConstants.FRAME_TYPE_END_RESPONSE, 1,
                buffer -> buffer.put((byte) 0)));
        assertInstanceOf(AjpClientChannel.EndResponse.class, data);
        assertFalse(channel.isOpen());
        assertFalse(channel.isLastFrameReceived());
        assertTrue(channel.isLastFrameSent());
    }

    @Test
    void parseFrameRecognisesCpong() throws Exception {
        AjpClientChannel channel = newClientChannel();
        FrameHeaderData data = channel.parseFrame(AjpTestSupport.bytes(0x41, 0x42, 0x00, 0x01, AjpConstants.FRAME_TYPE_CPONG));
        AjpClientChannel.CpongResponse cpong = assertInstanceOf(AjpClientChannel.CpongResponse.class, data);
        assertEquals(0, cpong.getFrameLength());
        assertNull(cpong.getExistingChannel());
    }

    @Test
    void createChannelHandlesRequestBodyChunkAndClosesData() throws Exception {
        AjpClientChannel channel = newClientChannel();
        AjpClientRequestClientStreamSinkChannel request = AjpTestSupport.request(channel, Methods.POST, "/",
                new HeaderMap(), AjpTestSupport.attachable());
        assertNotNull(request);

        FrameHeaderData requested = channel.parseFrame(responseFrame(AjpConstants.FRAME_TYPE_REQUEST_BODY_CHUNK, 2,
                buffer -> putInt(buffer, 17)));
        TrackingPooledByteBuffer data = new TrackingPooledByteBuffer();
        assertNull(channel.createChannel(requested, data));
        assertTrue(data.isClosed());
    }

    @Test
    void createChannelRejectsUnknownFrameAndClosesData() {
        AjpClientChannel channel = newClientChannel();
        FrameHeaderData unknown = new FrameHeaderData() {
            @Override
            public long getFrameLength() {
                return 0;
            }

            @Override
            public AbstractFramedStreamSourceChannel<?, ?, ?> getExistingChannel() {
                return null;
            }
        };
        TrackingPooledByteBuffer data = new TrackingPooledByteBuffer();

        RuntimeException exception = assertThrows(RuntimeException.class, () -> channel.createChannel(unknown, data));
        assertEquals("TODO: unknown frame", exception.getMessage());
        assertTrue(data.isClosed());
    }

    @Test
    void sourceDoneWithoutSinkDonePutsRequestIntoDiscardMode() throws Exception {
        AjpClientChannel channel = newClientChannel();
        AjpClientRequestClientStreamSinkChannel request = AjpTestSupport.request(channel, Methods.POST, "/",
                new HeaderMap(), AjpTestSupport.attachable());

        channel.sourceDone();

        SendFrameHeader header = request.generateSendFrameHeader();
        assertNotNull(header.getByteBuffer());
        assertEquals(0, header.getByteBuffer().getBuffer().remaining());
        assertEquals(0, header.getRemainingInBuffer());

        channel.sinkDone();
        assertEquals(0, channel.getReceivers().size());
        assertNotNull(AjpTestSupport.request(channel, Methods.GET, "/", new HeaderMap(), AjpTestSupport.attachable()));
    }

    @Test
    void channelExposesSettingsAndBufferPool() {
        AjpClientChannel channel = newClientChannel();
        assertNotNull(channel.getBufferPool());
        assertNotNull(channel.getSettings());
        assertTrue(channel.getSettings().isEmpty());
        assertEquals(4096, channel.getBufferPool().getBufferSize());
    }

    @Test
    void closeSubChannelsDoesNotFailWhenNoSubChannelsExist() {
        AjpClientChannel channel = newClientChannel();
        channel.closeSubChannels();
        Collection<AbstractFramedStreamSourceChannel<AjpClientChannel, AbstractAjpClientStreamSourceChannel, AbstractAjpClientStreamSinkChannel>> receivers = channel.getReceivers();
        assertEquals(0, receivers.size());
    }

    @Test
    void settingsAreReadFromOptionMap() {
        AjpClientChannel channel = newClientChannel();
        assertFalse(channel.getSettings().contains(Option.simple(OptionMap.class, "missing")));
        assertTrue(channel.getSettings().isEmpty());
    }

    @Test
    void parseFrameWithIncompleteDataReturnsNull() throws Exception {
        AjpClientChannel channel = newClientChannel();
        assertNull(channel.parseFrame(AjpTestSupport.bytes(0x41)));
        assertNull(channel.parseFrame(AjpTestSupport.bytes(0x41, 0x42, 0x00)));
    }

    @Test
    void isLastFrameFlagsInitiallyFalse() {
        AjpClientChannel channel = newClientChannel();
        assertFalse(channel.isLastFrameReceived());
        assertFalse(channel.isLastFrameSent());
    }

    private static final class TrackingPooledByteBuffer implements PooledByteBuffer {
        private boolean closed;

        @Override
        public ByteBuffer getBuffer() {
            return ByteBuffer.allocate(0);
        }

        @Override
        public void close() {
            closed = true;
        }

        @Override
        public boolean isOpen() {
            return !closed;
        }

        boolean isClosed() {
            return closed;
        }
    }
}
