class AjpClientCPingStreamSinkChannelTest {

    @Test
    void cpingFrameHasTheProtocolDefinedPayload() {
        AjpClientCPingStreamSinkChannel channel = new AjpClientCPingStreamSinkChannel(newClientChannel());

        SendFrameHeader header = channel.createFrameHeader();
        ByteBuffer buffer = header.getByteBuffer().getBuffer();
