    @Test
    void cpingChannelIsNotTheLastFrame() {
        AjpClientCPingStreamSinkChannel channel = new AjpClientCPingStreamSinkChannel(newClientChannel());
        assertFalse(channel.isLastFrame());
    }

    @Test
    void cpingChannelIsWritableUntilShutdown() throws Exception {
        AjpClientCPingStreamSinkChannel channel = new AjpClientCPingStreamSinkChannel(newClientChannel());
        assertFalse(channel.isWritesShutdown());
        channel.shutdownWrites();
        assertEquals(true, channel.isWritesShutdown());
    }
}
