package io.undertow.server.handlers.builder;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

import io.undertow.predicate.Predicate;
import io.undertow.predicate.PredicatesHandler;
import io.undertow.server.HandlerWrapper;
import io.undertow.server.HttpHandler;
import io.undertow.server.HttpServerExchange;
import io.undertow.util.Methods;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Tests for the textual handler/predicate parser.
 */
class PredicatedHandlersParserTest {

    @TempDir
    Path tempDir;

    private static ClassLoader classLoader() {
        return PredicatedHandlersParserTest.class.getClassLoader();
    }

    // ------------------------------------------------------------------
    // tokenizer
    // ------------------------------------------------------------------

    @Test
    void tokenizeSplitsASimpleHandlerCall() {
        assertEquals(List.of("response-code", "(", "404", ")"), tokens("response-code(404)"));
    }

    @Test
    void tokenizeHandlesNamedParametersAndArrow() {
        assertEquals(List.of("path", "(", "/foo", ")", "->", "response-code", "(", "200", ")"),
                tokens("path('/foo') -> response-code(200)"));
    }

    @Test
    void tokenizeHandlesQuotedAndBracketSyntax() {
        assertEquals(List.of("rewrite", "[", "value", "=", "/path", "]"),
                tokens("rewrite[value=\"/path\"]"));
    }

    @Test
    void tokenizeHandlesCurlyBraceArrays() {
        assertEquals(List.of("path", "(", "{", "/a", ",", "/b", "}", ")"),
                tokens("path({'/a','/b'})"));
    }

    @Test
    void tokenizeUnescapesQuotesInsideQuotedValues() {
        assertEquals(List.of("reason-phrase", "(", "it's", ")"), tokens("reason-phrase('it\\'s')"));
    }

    @Test
    void tokenizeKeepsExchangeAttributeTokensIntact() {
        assertEquals(List.of("rewrite", "[", "value", "=", "%{RELATIVE_PATH}", "]"),
                tokens("rewrite[value=%{RELATIVE_PATH}]"));
    }

    @Test
    void tokenizeEmitsStatementSeparators() {
        assertEquals(List.of("response-code", "(", "200", ")", ";", "response-code", "(", "404", ")"),
                tokens("response-code(200);response-code(404)"));
    }

    @Test
    void tokenizeSkipsWholeLineComments() {
        List<String> tokens = tokens("# this line is ignored\nresponse-code(200)");

        assertTrue(tokens.contains("response-code"));
        assertFalse(tokens.contains("#"));
        assertFalse(tokens.contains("ignored"));
    }

    @Test
    void tokenizeOfEmptyStringProducesNoTokens() {
        assertTrue(tokens("").isEmpty());
    }

    // ------------------------------------------------------------------
    // handler parsing
    // ------------------------------------------------------------------

    @Test
    void parseHandlerWithDefaultParameter() throws Exception {
        HandlerWrapper wrapper = HandlerParser.parse("response-code(418)", classLoader());

        HttpServerExchange exchange = HandlerTestSupport.exchange();
        wrapper.wrap(noop()).handleRequest(exchange);
        assertEquals(418, exchange.getStatusCode());
    }

    @Test
    void parseHandlerWithNamedParameterAndOldStyleBrackets() throws Exception {
        HandlerWrapper wrapper = PredicatedHandlersParser.parseHandler("response-code[value=403]", classLoader());

        HttpServerExchange exchange = HandlerTestSupport.exchange();
        wrapper.wrap(noop()).handleRequest(exchange);
        assertEquals(403, exchange.getStatusCode());
    }

    @Test
    void parseHandlerWithQuotedStringParameter() throws Exception {
        HandlerWrapper wrapper = PredicatedHandlersParser.parseHandler("reason-phrase('Out to lunch')", classLoader());

        HttpServerExchange exchange = HandlerTestSupport.exchange();
        wrapper.wrap(noop()).handleRequest(exchange);
        assertEquals("Out to lunch", exchange.getReasonPhrase());
    }

    @Test
    void parseHandlerCoercesExchangeAttributeParameters() throws Exception {
        HandlerWrapper wrapper = PredicatedHandlersParser.parseHandler("rewrite('/static')", classLoader());

        HttpServerExchange exchange = HandlerTestSupport.exchange();
        wrapper.wrap(noop()).handleRequest(exchange);
        assertEquals("/static", exchange.getRelativePath());
        assertEquals("/static", exchange.getRequestURI());
    }

    @Test
    void parseHandlerParsesUndertowStyleAttributeExpressions() throws Exception {
        HandlerWrapper wrapper = PredicatedHandlersParser.parseHandler("rewrite(%{QUERY_STRING})", classLoader());

        HttpServerExchange exchange = HandlerTestSupport.exchange().setQueryString("value");
        wrapper.wrap(noop()).handleRequest(exchange);
        assertEquals("/value", exchange.getRelativePath());
    }

    @Test
    void parseHandlerCoercesArrayParameters() throws Exception {
        HandlerWrapper wrapper = PredicatedHandlersParser.parseHandler("allowed-methods(GET, POST)", classLoader());

        HandlerTestSupport.RecordingHandler next = new HandlerTestSupport.RecordingHandler();
        HttpHandler handler = wrapper.wrap(next);

        handler.handleRequest(HandlerTestSupport.exchange().setRequestMethod(Methods.POST));
        handler.handleRequest(HandlerTestSupport.exchange().setRequestMethod(Methods.GET));
        assertEquals(2, next.invocations);
    }

    @Test
    void parseHandlerRejectsUnknownHandler() {
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
                () -> PredicatedHandlersParser.parseHandler("no-such-handler(1)", classLoader()));

        assertTrue(e.getMessage().contains("no handler named no-such-handler"), e.getMessage());
    }

    @Test
    void parseHandlerRejectsMissingRequiredParameters() {
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
                () -> PredicatedHandlersParser.parseHandler("response-code()", classLoader()));

        assertTrue(e.getMessage().contains("required parameters [value] not provided for handler response-code"),
                e.getMessage());
    }

    @Test
    void parseHandlerRejectsUnknownParameters() {
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
                () -> PredicatedHandlersParser.parseHandler("response-code(other=200)", classLoader()));

        assertTrue(e.getMessage().contains("unknown parameter other"), e.getMessage());
    }

    @Test
    void parseHandlerRejectsArrayValueForScalarParameter() {
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
                () -> PredicatedHandlersParser.parseHandler("response-code(value={200,201})", classLoader()));

        assertTrue(e.getMessage().contains("parameter is not an array type value"), e.getMessage());
    }

    @Test
    void parseHandlerRejectsNonNumericIntegerParameter() {
        assertThrows(NumberFormatException.class,
                () -> PredicatedHandlersParser.parseHandler("response-code(not-a-number)", classLoader()));
    }

    @Test
    void parseHandlerRejectsUnclosedParameterList() {
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
                () -> PredicatedHandlersParser.parseHandler("response-code(200", classLoader()));

        assertTrue(e.getMessage().contains("Unexpected end of input"), e.getMessage());
    }

    @Test
    void parseHandlerRejectsUnexpectedToken() {
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
                () -> PredicatedHandlersParser.parseHandler("response-code(value=)", classLoader()));

        assertTrue(e.getMessage().contains("Error parsing predicated handler string"), e.getMessage());
    }

    // ------------------------------------------------------------------
    // predicate parsing
    // ------------------------------------------------------------------

    @Test
    void parsePredicateMatchesRequestMethod() {
        Predicate predicate = PredicatedHandlersParser.parsePredicate("method(GET)", classLoader());

        assertTrue(predicate.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.GET)));
        assertFalse(predicate.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.POST)));
    }

    @Test
    void parsePredicateMatchesRelativePath() {
        Predicate predicate = PredicatedHandlersParser.parsePredicate("path('/admin')", classLoader());

        assertTrue(predicate.resolve(HandlerTestSupport.exchange().setRelativePath("/admin")));
        assertFalse(predicate.resolve(HandlerTestSupport.exchange().setRelativePath("/admin/other")));
        assertFalse(predicate.resolve(HandlerTestSupport.exchange().setRelativePath("/public")));
    }

    @Test
    void parsePredicateSupportsMultiplePathValues() {
        Predicate predicate = PredicatedHandlersParser.parsePredicate("path({'/a','/b'})", classLoader());

        assertTrue(predicate.resolve(HandlerTestSupport.exchange().setRelativePath("/a")));
        assertTrue(predicate.resolve(HandlerTestSupport.exchange().setRelativePath("/b")));
        assertFalse(predicate.resolve(HandlerTestSupport.exchange().setRelativePath("/c")));
    }

    @Test
    void parsePredicateSupportsConstants() {
        assertTrue(PredicatedHandlersParser.parsePredicate("true", classLoader())
                .resolve(HandlerTestSupport.exchange()));
        assertFalse(PredicatedHandlersParser.parsePredicate("false", classLoader())
                .resolve(HandlerTestSupport.exchange()));
    }

    @Test
    void parsePredicateSupportsAndOrNot() {
        ClassLoader cl = classLoader();

        Predicate and = PredicatedHandlersParser.parsePredicate("method(GET) and path('/a')", cl);
        assertTrue(and.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.GET).setRelativePath("/a")));
        assertFalse(and.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.POST).setRelativePath("/a")));
        assertFalse(and.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.GET).setRelativePath("/b")));

        Predicate or = PredicatedHandlersParser.parsePredicate("method(PUT) or path('/a')", cl);
        assertTrue(or.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.PUT).setRelativePath("/z")));
        assertTrue(or.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.GET).setRelativePath("/a")));
        assertFalse(or.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.GET).setRelativePath("/z")));

        Predicate not = PredicatedHandlersParser.parsePredicate("not method(GET)", cl);
        assertFalse(not.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.GET)));
        assertTrue(not.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.POST)));
    }

    @Test
    void parsePredicateRejectsUnknownPredicate() {
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
                () -> PredicatedHandlersParser.parsePredicate("no-such-predicate('/a')", classLoader()));

        assertTrue(e.getMessage().contains("no predicate named no-such-predicate"), e.getMessage());
    }

    @Test
    void parsePredicateRejectsMissingRequiredParameters() {
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
                () -> PredicatedHandlersParser.parsePredicate("path()", classLoader()));

        assertTrue(e.getMessage().contains("required parameters [path] not provided for predicate path"),
                e.getMessage());
    }

    // ------------------------------------------------------------------
    // full document parsing
    // ------------------------------------------------------------------

    @Test
    void parseSingleRule() throws Exception {
        List<PredicatedHandler> handlers = PredicatedHandlersParser.parse(
                "path('/admin') -> response-code(403)", classLoader());

        assertEquals(1, handlers.size());
        PredicatedHandler handler = handlers.get(0);
        assertTrue(handler.getPredicate().resolve(HandlerTestSupport.exchange().setRelativePath("/admin")));
        assertFalse(handler.getPredicate().resolve(HandlerTestSupport.exchange().setRelativePath("/public")));
        assertNull(handler.getElseHandler());

        HttpServerExchange exchange = HandlerTestSupport.exchange();
        handler.getHandler().wrap(noop()).handleRequest(exchange);
        assertEquals(403, exchange.getStatusCode());
    }

    @Test
    void parseMultipleRules() throws Exception {
        List<PredicatedHandler> handlers = PredicatedHandlersParser.parse(
                "path('/a') -> response-code(200)\npath('/b') -> response-code(404)\n", classLoader());

        assertEquals(2, handlers.size());

        HttpServerExchange first = HandlerTestSupport.exchange();
        handlers.get(0).getHandler().wrap(noop()).handleRequest(first);
        assertEquals(200, first.getStatusCode());

        HttpServerExchange second = HandlerTestSupport.exchange();
        handlers.get(1).getHandler().wrap(noop()).handleRequest(second);
        assertEquals(404, second.getStatusCode());
    }

    @Test
    void parseRuleWithElseBranch() throws Exception {
        List<PredicatedHandler> handlers = PredicatedHandlersParser.parse(
                "method(GET) -> response-code(200) else response-code(405)", classLoader());

        assertEquals(1, handlers.size());
        PredicatedHandler handler = handlers.get(0);
        assertNotNull(handler.getElseHandler());

        Predicate predicate = handler.getPredicate();
        assertTrue(predicate.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.GET)));
        assertFalse(predicate.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.POST)));

        HttpServerExchange matched = HandlerTestSupport.exchange();
        handler.getHandler().wrap(noop()).handleRequest(matched);
        assertEquals(200, matched.getStatusCode());

        HttpServerExchange unmatched = HandlerTestSupport.exchange();
        handler.getElseHandler().wrap(noop()).handleRequest(unmatched);
        assertEquals(405, unmatched.getStatusCode());
    }

    @Test
    void parseRuleWithNestedBlockHandler() {
        List<PredicatedHandler> handlers = PredicatedHandlersParser.parse(
                "path('/a') -> { response-code(200); response-code(201); }", classLoader());

        assertEquals(1, handlers.size());
        HandlerWrapper block = handlers.get(0).getHandler();

        assertInstanceOf(PredicatesHandler.Wrapper.class, block);
        assertInstanceOf(PredicatesHandler.class, block.wrap(noop()));
    }

    @Test
    void parseTopLevelBlockWithSeveralRules() {
        List<PredicatedHandler> handlers = PredicatedHandlersParser.parse(
                "{ path('/a') -> response-code(200); path('/b') -> response-code(404); }", classLoader());

        assertEquals(2, handlers.size());
    }

    @Test
    void parseRuleWithCompoundPredicate() throws Exception {
        List<PredicatedHandler> handlers = PredicatedHandlersParser.parse(
                "method(GET) and not path('/blocked') -> response-code(200)", classLoader());

        assertEquals(1, handlers.size());
        Predicate predicate = handlers.get(0).getPredicate();
        assertTrue(predicate.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.GET).setRelativePath("/ok")));
        assertFalse(predicate.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.GET).setRelativePath("/blocked")));
        assertFalse(predicate.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.POST).setRelativePath("/ok")));
    }

    @Test
    void parseIgnoresCommentLines() {
        List<PredicatedHandler> handlers = PredicatedHandlersParser.parse(
                "# rules below\npath('/a') -> response-code(200)\n", classLoader());

        assertEquals(1, handlers.size());
    }

    @Test
    void parseEmptyDocumentProducesNoHandlers() {
        assertTrue(PredicatedHandlersParser.parse("", classLoader()).isEmpty());
        assertTrue(PredicatedHandlersParser.parse("# only a comment", classLoader()).isEmpty());
    }

    @Test
    void parseRejectsUnknownHandlerInRule() {
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
                () -> PredicatedHandlersParser.parse("path('/a') -> no-such-handler(1)", classLoader()));

        assertTrue(e.getMessage().contains("no handler named no-such-handler"), e.getMessage());
    }

    @Test
    void parseRejectsBarePredicateWithoutHandler() {
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
                () -> PredicatedHandlersParser.parse("path('/a')", classLoader()));

        assertTrue(e.getMessage().contains("no handler named path"), e.getMessage());
    }

    // ------------------------------------------------------------------
    // file based parsing
    // ------------------------------------------------------------------

    @Test
    void parseFromPathAndFileAgree() throws IOException {
        String contents = "path('/a') -> response-code(200)\npath('/b') -> response-code(404)\n";
        Path file = tempDir.resolve("undertow-handlers.conf");
        Files.write(file, contents.getBytes(StandardCharsets.UTF_8));

        List<PredicatedHandler> fromPath = PredicatedHandlersParser.parse(file, classLoader());
        List<PredicatedHandler> fromFile = PredicatedHandlersParser.parse(file.toFile(), classLoader());

        assertEquals(2, fromPath.size());
        assertEquals(2, fromFile.size());
    }

    @Test
    void parseFromInputStream() throws Exception {
        String contents = "path('/a') -> response-code(201)";
        List<PredicatedHandler> handlers = PredicatedHandlersParser.parse(
                new ByteArrayInputStream(contents.getBytes(StandardCharsets.UTF_8)), classLoader());

        assertEquals(1, handlers.size());
        HttpServerExchange exchange = HandlerTestSupport.exchange();
        handlers.get(0).getHandler().wrap(noop()).handleRequest(exchange);
        assertEquals(201, exchange.getStatusCode());
    }

    // ------------------------------------------------------------------
    // helpers
    // ------------------------------------------------------------------

    private static List<String> tokens(String input) {
        List<String> result = new ArrayList<>();
        for (PredicatedHandlersParser.Token token : PredicatedHandlersParser.tokenize(input)) {
            result.add(token.getToken());
        }
        return result;
    }

    private static HttpHandler noop() {
        return exchange -> {
        };
    }
}
