import java.nio.charset.StandardCharsets;
import java.util.Arrays;

import io.undertow.security.impl.ExternalAuthenticationMechanism;
import io.undertow.server.HttpServerExchange;
import io.undertow.util.BadRequestException;
import io.undertow.util.Headers;
import io.undertow.util.HttpString;
import io.undertow.util.Methods;
import io.undertow.util.UrlDecodeException;
import org.junit.jupiter.api.Test;

class AjpRequestParserTest {

    private static AjpRequestParser parser() {
        return new AjpRequestParser("UTF-8", true, 20, 20, false, false);
    }

    private static HttpServerExchange exchange() {
        return new HttpServerExchange(null);
    }

    @Test
    void parsesAForwardRequestWithHeadersAddressesAndScheme() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();
        HttpServerExchange exchange = exchange();
        ByteBuffer packet = new AjpTestSupport.RequestBuilder()
                .method(2)
                .requestUri("/app/hello%20world")
                .remoteAddress("192.0.2.10")
                .remoteHost("client.example")
                .serverName("server.example")
                .serverPort(8443)
                .ssl(true)
                .commonHeader(0xB, "example.test:8443")
                .header("X-Trace", "one")
                .header("X-Trace", "two")
                .build();

        parser().parse(packet, state, exchange);

        assertAllState(state, exchange);
        assertEquals(2, state.prefix);
        assertTrue(state.dataSize > 0);
        assertEquals(Methods.GET, exchange.getRequestMethod());
        assertEquals("HTTP/1.1", exchange.getProtocol().toString());
        assertEquals("https", exchange.getRequestScheme());
        assertEquals("/app/hello%20world", exchange.getRequestURI());
        assertEquals("/app/hello world", exchange.getRequestPath());
        assertEquals("/app/hello world", exchange.getRelativePath());
        assertEquals("192.0.2.10", state.remoteAddress);
        assertEquals("server.example", state.serverAddress);
        assertEquals(8443, state.serverPort);
        assertEquals("example.test:8443", exchange.getRequestHeaders().getFirst(Headers.HOST));
        assertEquals(Arrays.asList("one", "two"), exchange.getRequestHeaders().get("X-Trace"));
    }

    private static void assertAllState(AjpRequestParseState state, HttpServerExchange exchange) {
        assertTrue(state.isComplete());
        assertNotNull(exchange.getRequestHeaders());
    }

    @Test
    void parsesAPacketDeliveredOneByteAtATime() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();
        HttpServerExchange exchange = exchange();
        ByteBuffer full = new AjpTestSupport.RequestBuilder()
                .method(4)
                .requestUri("/fragmented")
                .header("X-Fragment", "works")
                .attribute(AjpRequestParser.QUERY_STRING.equals("query_string") ? 5 : 5, "a=1")
                .build();
        AjpRequestParser parser = parser();

        while (full.hasRemaining()) {
            ByteBuffer oneByte = ByteBuffer.wrap(new byte[] {full.get()});
            parser.parse(oneByte, state, exchange);
            assertFalse(oneByte.hasRemaining(), "the parser must consume a complete one-byte slice");
        }

        assertTrue(state.isComplete());
        assertEquals(Methods.POST, exchange.getRequestMethod());
        assertEquals("/fragmented", exchange.getRequestPath());
        assertEquals("works", exchange.getRequestHeaders().getFirst("X-Fragment"));
        assertEquals("1", exchange.getQueryParameters().get("a").peekFirst());
    }

    @Test
    void rejectsAWrongMagicNumber() {
        ByteBuffer packet = ByteBuffer.wrap(new byte[] {0x12, 0x35, 0x00, 0x01, 0x02});
        assertBadRequest(() -> parser().parse(packet, new AjpRequestParseState(), exchange()));
    }

    @Test
    void rejectsAnUnknownMethodCode() {
        ByteBuffer packet = new AjpTestSupport.RequestBuilder().method(99).build();
        assertBadRequest(() -> parser().parse(packet, new AjpRequestParseState(), exchange()));
    }

    @Test
    void completesImmediatelyForNonForwardPrefixes() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();
        HttpServerExchange exchange = exchange();

        parser().parse(simplePacket(AjpRequestParser.CPING), state, exchange);

        assertTrue(state.isComplete());
        assertEquals(AjpRequestParser.CPING, state.prefix);
        assertEquals(Methods.EMPTY, exchange.getRequestMethod());
        assertNull(exchange.getRequestPath());
    }

    @Test
    void marksTooManyHeadersAsBadRequestAndDoesNotPopulateTheHeaderMap() throws Exception {
        AjpRequestParser parser = new AjpRequestParser("UTF-8", true, 10, 1, false, false);
        AjpRequestParseState state = new AjpRequestParseState();
        HttpServerExchange exchange = exchange();
        ByteBuffer packet = new AjpTestSupport.RequestBuilder()
                .header("X-One", "1")
                .header("X-Two", "2")
                .build();

        parser.parse(packet, state, exchange);

        assertTrue(state.isComplete());
        assertTrue(state.badRequest);
        assertFalse(exchange.getRequestHeaders().contains("X-One"));
        assertFalse(exchange.getRequestHeaders().contains("X-Two"));
    }

    @Test
    void mapsEncodedHeaderCodesAndPreservesRepeatedValues() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();
        HttpServerExchange exchange = exchange();
        ByteBuffer packet = new AjpTestSupport.RequestBuilder()
                .commonHeader(0x7, "text/plain")
                .commonHeader(0x8, "12")
                .commonHeader(0x9, "a=1")
                .commonHeader(0x9, "b=2")
                .header("X-Custom", "value")
                .build();

        parser().parse(packet, state, exchange);

        assertEquals("text/plain", exchange.getRequestHeaders().getFirst(Headers.CONTENT_TYPE));
        assertEquals("12", exchange.getRequestHeaders().getFirst(Headers.CONTENT_LENGTH));
        assertEquals(Arrays.asList("a=1", "b=2"), exchange.getRequestHeaders().get(Headers.COOKIE));
        assertEquals("value", exchange.getRequestHeaders().getFirst("X-Custom"));
    }

    @Test
