package io.undertow.servlet.compat.rewrite;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

class ResolverTest {

    private static final String PROPERTY = "undertow.rewrite.resolver.test";

    @AfterEach
    void clearProperty() {
        System.clearProperty(PROPERTY);
    }

    @Test
    void defaultResolveEnvReadsSystemProperty() {
        System.setProperty(PROPERTY, "configured");

        assertEquals("configured", new StubResolver().resolveEnv(PROPERTY));
    }

    @Test
    void testResolverReceivesEveryLookupKind() {
        StubResolver resolver = new StubResolver();

        assertEquals("request", resolver.resolve("key"));
        assertEquals("env", resolver.resolveEnv("key"));
        assertEquals("ssl", resolver.resolveSsl("key"));
        assertEquals("http", resolver.resolveHttp("key"));
        assertTrue(resolver.resolveResource(1, "/index.html"));
        assertFalse(resolver.resolveResource(2, "/empty"));
        assertNull(new StubResolver().resolveEnv("definitely.not.set." + System.nanoTime()));
    }

    private static final class StubResolver extends Resolver {
        @Override
        public String resolve(String key) {
            return "request";
        }

        @Override
        public String resolveSsl(String key) {
            return "ssl";
        }

        @Override
        public String resolveHttp(String key) {
            return "http";
        }

        @Override
        public boolean resolveResource(int type, String name) {
            return type == 1;
        }

        @Override
        public String resolveEnv(String key) {
            return key.equals("key") ? "env" : super.resolveEnv(key);
        }
    }
}
