package io.undertow.servlet.compat.rewrite;

import org.junit.jupiter.api.Test;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;

class RewriteConfigTest {

    @Test
    void exposesRulesAndMapsThroughConstructedConfig() {
        RewriteRule rule = new RewriteRule();
        rule.setPatternString("^/old$");
        rule.setSubstitutionString("/new");
        RewriteRule[] rules = {rule};
        Map<String, RewriteMap> maps = new HashMap<>();

        RewriteConfig config = new RewriteConfig(rules, maps);

        assertArrayEquals(rules, config.getRules());
        assertSame(maps, config.getMaps());
    }

    @Test
    void toStringPrintsConditionsBeforeTheirRuleAndSeparatesRules() {
        RewriteCond condition = new RewriteCond();
        condition.setTestString("%{HTTP_HOST}");
        condition.setCondPattern("^example");
        RewriteRule first = new RewriteRule();
        first.setPatternString("^/one$");
        first.setSubstitutionString("/first");
        first.addCondition(condition);
        RewriteRule second = new RewriteRule();
        second.setPatternString("^/two$");
        second.setSubstitutionString("/second");

        RewriteConfig config = new RewriteConfig(new RewriteRule[]{first, second}, Collections.emptyMap());

        assertEquals("RewriteCond %{HTTP_HOST} ^example\r\n"
                + "RewriteRule ^/one$ /first\r\n\r\n"
                + "RewriteRule ^/two$ /second\r\n\r\n", config.toString());
    }

    @Test
    void emptyConfigHasEmptyStringRepresentation() {
        RewriteConfig config = new RewriteConfig(new RewriteRule[0], Collections.emptyMap());

        assertEquals("", config.toString());
    }
}
