package io.undertow.servlet.compat.rewrite;

import org.junit.jupiter.api.Test;

import java.util.Collections;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

class RewriteCondTest {

    private static final Resolver NO_RESOLVER = new StubResolver();

    @Test
    void patternConditionMatchesWholeValueAndKeepsMatcher() {
        RewriteCond condition = condition("abc-123", "abc-(\\d+)");

        assertTrue(condition.evaluate(null, null, NO_RESOLVER));
        Matcher matcher = condition.getMatcher();
        assertNotNull(matcher);
        assertEquals("123", matcher.group(1));
    }

    @Test
    void patternConditionDoesNotMatchAPartialValue() {
        RewriteCond condition = condition("prefix-abc", "abc");

        assertFalse(condition.evaluate(null, null, NO_RESOLVER));
        assertNull(condition.getMatcher());
    }

    @Test
    void patternConditionExpandsRuleBackReference() {
        RewriteCond condition = condition("$1", "value");
        Matcher rule = Pattern.compile("(value)").matcher("value");

        assertTrue(condition.evaluate(rule, null, NO_RESOLVER));
    }

    @Test
    void patternConditionExpandsPreviousConditionBackReference() {
        RewriteCond condition = condition("%1", "captured");
        Matcher previous = Pattern.compile("(captured)").matcher("captured");

        assertTrue(condition.evaluate(null, previous, NO_RESOLVER));
        assertEquals("captured", condition.getMatcher().group(0));
    }

    @Test
    void nocaseMakesPatternMatchingCaseInsensitive() {
        RewriteCond condition = condition("ABC", "abc");
        condition.setNocase(true);

        assertTrue(condition.evaluate(null, null, NO_RESOLVER));
    }

    @Test
    void patternMatchingIsCaseSensitiveByDefault() {
        RewriteCond condition = condition("ABC", "abc");

        assertFalse(condition.evaluate(null, null, NO_RESOLVER));
    }

    @Test
    void leadingBangNegatesConditionAndIsRemovedFromPattern() {
        RewriteCond condition = condition("public", "!^private$");

        assertEquals("^private$", condition.getCondPattern());
        assertFalse(condition.isPositive());
        assertTrue(condition.evaluate(null, null, NO_RESOLVER));
        assertFalse(condition.evaluate(null, null, NO_RESOLVER) == condition.evaluate(null, null, NO_RESOLVER)
                && !condition.evaluate(null, null, NO_RESOLVER));
    }

    @Test
    void negatedConditionFailsWhenUnderlyingPatternMatches() {
        RewriteCond condition = condition("private", "!^private$");

        assertFalse(condition.evaluate(null, null, NO_RESOLVER));
    }

    @Test
    void lexicalConditionsCompareTestStringToOperand() {
        assertTrue(condition("b", ">a").evaluate(null, null, NO_RESOLVER));
        assertFalse(condition("b", ">b").evaluate(null, null, NO_RESOLVER));
        assertTrue(condition("b", "<c").evaluate(null, null, NO_RESOLVER));
        assertFalse(condition("b", "<a").evaluate(null, null, NO_RESOLVER));
        assertTrue(condition("same", "=same").evaluate(null, null, NO_RESOLVER));
        assertFalse(condition("different", "=same").evaluate(null, null, NO_RESOLVER));
    }

    @Test
    void nocaseLowercasesExpandedTestStringBeforePatternMatching() {
        RewriteCond condition = condition("$1", "mixed");
        condition.setNocase(true);
        Matcher rule = Pattern.compile("(MiXeD)").matcher("MiXeD");

        assertTrue(condition.evaluate(rule, null, NO_RESOLVER));
    }

    @Test
    void resourceConditionsAcceptKnownTypesAndRejectUnknownType() {
        assertTrue(condition("anything", "-d").evaluate(null, null, NO_RESOLVER));
        assertTrue(condition("anything", "-f").evaluate(null, null, NO_RESOLVER));
        assertTrue(condition("anything", "-s").evaluate(null, null, NO_RESOLVER));

        RewriteCond.ResourceCondition invalid = new RewriteCond.ResourceCondition();
        invalid.type = 99;
        assertFalse(invalid.evaluate("anything", NO_RESOLVER));
    }

    @Test
    void lexicalConditionRejectsUnknownComparisonType() {
        RewriteCond.LexicalCondition invalid = new RewriteCond.LexicalCondition();
        invalid.type = 42;
        invalid.condition = "x";

        assertFalse(invalid.evaluate("x", NO_RESOLVER));
    }

    @Test
    void conditionCanBeEvaluatedRepeatedlyWithoutRecompilingStateLoss() {
        RewriteCond condition = condition("first", "^first$");

        assertTrue(condition.evaluate(null, null, NO_RESOLVER));
        assertEquals("first", condition.getMatcher().group(0));
        assertTrue(condition.evaluate(null, null, NO_RESOLVER));
    }

    @Test
    void accessorsRoundTripConfiguration() {
        RewriteCond condition = new RewriteCond();
        condition.setTestString("%{REQUEST_URI}");
        condition.setCondPattern("^/app/");
        condition.setNocase(true);
        condition.setOrnext(true);
        condition.setPositive(false);

        assertEquals("%{REQUEST_URI}", condition.getTestString());
        assertEquals("^/app/", condition.getCondPattern());
        assertTrue(condition.isNocase());
        assertTrue(condition.isOrnext());
        assertFalse(condition.isPositive());
    }

    @Test
    void stringRepresentationIncludesTestAndConditionPattern() {
        assertEquals("RewriteCond %{HTTP_HOST} ^www\\.example\\.com$",
                condition("%{HTTP_HOST}", "^www\\.example\\.com$").toString());
    }

    private static RewriteCond condition(String testString, String condPattern) {
        RewriteCond condition = new RewriteCond();
        condition.setTestString(testString);
        condition.setCondPattern(condPattern);
        condition.parse(Collections.emptyMap());
        return condition;
    }

    private static final class StubResolver extends Resolver {
        @Override
        public String resolve(String key) {
            return null;
        }

        @Override
        public String resolveSsl(String key) {
            return null;
        }

        @Override
        public String resolveHttp(String key) {
            return null;
        }

        @Override
        public boolean resolveResource(int type, String name) {
            return false;
        }
    }
}
