                case "getRemoteHost":
                    return "client.example.test";
                case "getRemotePort":
                    return 4567;
                case "getRemoteUser":
                    return "alice";
                case "getMethod":
                    return "GET";
                case "getServletPath":
                    return "/index.jsp";
                case "getPathInfo":
                    return null;
                case "getQueryString":
                    return "x=1";
                case "getContextPath":
                    return "/app";
                case "getAuthType":
                    return "BASIC";
                case "getLocalName":
                    return "server.example.test";
                case "getLocalAddr":
                    return "127.0.0.1";
                case "getLocalPort":
                    return 8080;
                case "getProtocol":
                    return "HTTP/1.1";
                case "getRequestURI":
                    return "/app/index.jsp";
