    void redirectUsesConfiguredStatusAppendsQueryAndContextPath() throws Exception {
        Response configuredStatus = get("/redir?x=1");
        assertEquals(301, configuredStatus.status);
        assertTrue(configuredStatus.location.endsWith("/app/redir-target?x=1"), configuredStatus.location);

