package io.undertow.websockets.jsr;

import jakarta.websocket.Session;
import java.util.Collections;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

/**
 * @author Stuart Douglas
 */
public class SessionContainer {

    private Runnable doneTask;
    private volatile int waiterCount;
    private final Set<Session> openSessions = Collections.newSetFromMap(new ConcurrentHashMap<Session, Boolean>());

    public Set<Session> getOpenSessions() {
        return Collections.unmodifiableSet(openSessions);
    }

    public void addOpenSession(Session session) {
        synchronized (this) {
            openSessions.add(session);
        }
    }

    public void removeOpenSession(Session session) {
        Runnable task = null;
        synchronized (this) {
            openSessions.remove(session);
            if (waiterCount > 0 && openSessions.isEmpty()) {
                notifyAll();
            }
            if(doneTask != null) {
                task = doneTask;
                doneTask = null;
            }
        }
        if(task != null) {
            task.run();
        }
    }

    public void awaitClose(long timeout) {
        synchronized (this) {
            if(openSessions.isEmpty()) {
                return;
            }
            waiterCount++;
            long cur,end = System.currentTimeMillis() + timeout;
            try {
                while ((cur=System.currentTimeMillis()) < end && !openSessions.isEmpty()) {
                    wait(end - cur);
                }
            } catch (InterruptedException e) {
                //ignore
            } finally {
                waiterCount--;
            }
        }
    }

    public void notifyClosed(Runnable done) {
        boolean run = false;
        synchronized (this) {
            if(openSessions.isEmpty()) {
                run = true;
            } else {
                this.doneTask = done;
            }
        }
        if(run) {
            done.run();
        }
    }
}
