    void createsEndpointsOnlyForInstancesOfTheDeclaredClass() throws Exception {
        AnnotatedEndpointFactory factory = create(ValidEndpoint.class);

        assertNotNull(factory.createInstance(new AnnotatedEndpointTestSupport.RecordingInstanceHandle<>(new ValidEndpoint())));
        assertThrows(IllegalArgumentException.class,
                () -> factory.createInstance(new AnnotatedEndpointTestSupport.RecordingInstanceHandle<>("not an endpoint")));
    }

    @Test
    void rejectsDuplicateOnOpenMethods() {
        assertThrows(DeploymentException.class, () -> create(DuplicateOpen.class));
    }

    @Test
    void rejectsOverloadedOnOpenMethods() {
        assertThrows(DeploymentException.class, () -> create(OverloadedOpen.class));
    }

    @Test
    void rejectsMultipleTextMessageHandlers() {
        assertThrows(DeploymentException.class, () -> create(MultipleTextMessages.class));
    }

    @Test
    void rejectsMessageMethodsWithoutARecognisedPayload() {
        assertThrows(DeploymentException.class, () -> create(UnrecognisedPayload.class));
        assertThrows(DeploymentException.class, () -> create(NoPayload.class));
        assertThrows(DeploymentException.class, () -> create(PathParameterOnly.class));
    }

    @Test
    void rejectsDuplicateSessionParameters() {
        assertThrows(IllegalArgumentException.class, () -> create(DuplicateSessionParameter.class));
    }

    @Test
    void rejectsAnOnErrorMethodWithoutAThrowableParameter() {
        assertThrows(IllegalArgumentException.class, () -> create(ErrorWithoutThrowable.class));
    }

    @Test
    void rejectsPathParametersThatCannotBeDecodedByTheDefaultEncodingFactory() {
        assertThrows(DeploymentException.class,
                () -> AnnotatedEndpointFactory.create(
                        UnsupportedPathType.class,
                        EncodingFactory.DEFAULT,
                        Collections.singleton("id")));
    }

    private static AnnotatedEndpointFactory create(Class<?> type) throws DeploymentException {
        return AnnotatedEndpointFactory.create(type, EncodingFactory.DEFAULT, Collections.emptySet());
    }

    public static class ValidEndpoint {
        @OnOpen
        public void open(Session session, EndpointConfig config) {
        }
    }

    public static class DuplicateOpen {
        @OnOpen
        public void first(Session session) {
        }

        @OnOpen
        public void second(Session session) {
        }
    }

    public static class OverloadedOpen {
        @OnOpen
        public void open(Session session) {
        }

        @OnOpen
        public void open(Session session, EndpointConfig config) {
        }
    }

    public static class MultipleTextMessages {
        @OnMessage
        public void first(String message) {
        }

        @OnMessage
        public void second(String message) {
        }
    }

    public static class UnrecognisedPayload {
        @OnMessage
        public void message(Object payload) {
        }
    }

    public static class NoPayload {
        @OnMessage
        public void message(Session session) {
        }
    }

    public static class PathParameterOnly {
        @OnMessage
        public void message(@PathParam("id") String id) {
        }
    }

    public static class DuplicateSessionParameter {
        @OnOpen
        public void open(Session first, Session second) {
        }
    }

    public static class ErrorWithoutThrowable {
        @OnError
        public void error(Session session) {
        }
    }

    public static class UnsupportedPathType {
        @OnOpen
        public void open(@PathParam("id") Object id) {
        }
    }
}
