class AnnotatedEndpointMessageHandlingTest {

    @Test
    void wholeTextHandlerIsRegisteredAndHonoursMaxMessageSize() throws Exception {
        WholeTextEndpoint target = new WholeTextEndpoint();
        AnnotatedEndpointTestSupport.EndpointFixture endpoint = AnnotatedEndpointTestSupport.endpointWithHandle(
                WholeTextEndpoint.class, target);
        AnnotatedEndpointTestSupport.SessionFixture fixture = AnnotatedEndpointTestSupport.newSession(
                endpoint.endpoint, Map.of());

        endpoint.endpoint.onOpen(fixture.session, EmptyEndpointConfig.INSTANCE);
        MessageHandler.Whole<String> handler = whole(fixture.session, String.class);
        handler.onMessage("hello");

        assertEquals("hello", target.message);
        assertEquals(1024, fixture.session.getMaxTextMessageBufferSize());
    }

    @Test
    void wholeBinaryHandlersAcceptByteArraysAndByteBuffers() throws Exception {
        WholeByteArrayEndpoint arrayTarget = new WholeByteArrayEndpoint();
        AnnotatedEndpointTestSupport.EndpointFixture arrayEndpoint = AnnotatedEndpointTestSupport.endpointWithHandle(
                WholeByteArrayEndpoint.class, arrayTarget);
        AnnotatedEndpointTestSupport.SessionFixture arrayFixture = AnnotatedEndpointTestSupport.newSession(
                arrayEndpoint.endpoint, Map.of());
        arrayEndpoint.endpoint.onOpen(arrayFixture.session, EmptyEndpointConfig.INSTANCE);
        whole(arrayFixture.session, byte[].class).onMessage(new byte[] {1, 2, 3});
        assertArrayEquals(new byte[] {1, 2, 3}, arrayTarget.message);
        assertEquals(2048, arrayFixture.session.getMaxBinaryMessageBufferSize());

        WholeByteBufferEndpoint bufferTarget = new WholeByteBufferEndpoint();
        AnnotatedEndpointTestSupport.EndpointFixture bufferEndpoint = AnnotatedEndpointTestSupport.endpointWithHandle(
                WholeByteBufferEndpoint.class, bufferTarget);
        AnnotatedEndpointTestSupport.SessionFixture bufferFixture = AnnotatedEndpointTestSupport.newSession(
                bufferEndpoint.endpoint, Map.of());
        bufferEndpoint.endpoint.onOpen(bufferFixture.session, EmptyEndpointConfig.INSTANCE);
        ByteBuffer value = ByteBuffer.wrap(new byte[] {4, 5});
        whole(bufferFixture.session, ByteBuffer.class).onMessage(value);
        assertEquals(value, bufferTarget.message);
    }

    @Test
    void partialTextHandlerReceivesTheLastFragmentFlag() throws Exception {
        PartialTextEndpoint target = new PartialTextEndpoint();
        AnnotatedEndpointTestSupport.EndpointFixture endpoint = AnnotatedEndpointTestSupport.endpointWithHandle(
                PartialTextEndpoint.class, target);
        AnnotatedEndpointTestSupport.SessionFixture fixture = AnnotatedEndpointTestSupport.newSession(
                endpoint.endpoint, Map.of());

        endpoint.endpoint.onOpen(fixture.session, EmptyEndpointConfig.INSTANCE);
        MessageHandler.Partial<String> handler = partial(fixture.session, String.class);
        handler.onMessage("first", false);
        handler.onMessage("last", true);

        assertEquals("firstlast", target.message.toString());
        assertFalse(target.firstLast);
        assertTrue(target.secondLast);
    }

    @Test
    void partialBinaryHandlerReceivesTheLastFragmentFlag() throws Exception {
        PartialBinaryEndpoint target = new PartialBinaryEndpoint();
        AnnotatedEndpointTestSupport.EndpointFixture endpoint = AnnotatedEndpointTestSupport.endpointWithHandle(
